package student // package main import "github.com/01-edu/z01" func EightQueens() { var board [8]int solver(0, &board) } // Print the array func printBoard(board *[8]int) { for i := 0; i < 8; i++ { z01.PrintRune(rune(board[i] + 1 + '0')) } z01.PrintRune('\n') } func isSafe(row, col int, board *[8]int) bool { for c := 0; c < col; c++ { r := board[c] if r == row || abs(r-row) == abs(c-col) { return false } } return true } func abs(x int) int { if x < 0 { return -x } return x } func solver(colomn int, board *[8]int) { if colomn == 8 { printBoard(board) return } for row := 0; row < 8; row++ { if isSafe(row, colomn, board) { board[colomn] = row solver(colomn+1, board) } } } // func main() { // EightQueens() // }
